function E([string]$v) { [Security.SecurityElement]::Escape($v) }
function Start-Svg([string]$title,[string]$sub,[string]$active) {
  $nav = @('工作台','客服案件','交易差异','内容审核','黄页管理','节假日与资讯','商品运营','订单运营')
  $s = '<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="820" viewBox="0 0 1200 820"><defs><linearGradient id="nav" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#10284D"/><stop offset="1" stop-color="#0C1D38"/></linearGradient><filter id="s"><feDropShadow dx="0" dy="6" stdDeviation="12" flood-color="#17345F" flood-opacity=".08"/></filter></defs><rect width="1200" height="820" rx="18" fill="#F3F6FA"/><rect width="228" height="820" fill="url(#nav)"/><g font-family="'+$font+'"><text x="32" y="48" font-size="20" font-weight="700" fill="#FFF">华人在孟 · 运营台</text>'
  for($i=0;$i -lt $nav.Count;$i++){ $y=94+$i*52; if($nav[$i] -eq $active){$s+='<rect x="16" y="'+($y-28)+'" width="196" height="40" rx="12" fill="#195BB8"/>'}; $s+='<text x="40" y="'+$y+'" font-size="14" fill="#'+($(if($nav[$i] -eq $active){'FFFFFF'}else{'B9C8DE'}))+'">'+(E $nav[$i])+'</text>' }
  $s += '<circle cx="48" cy="776" r="18" fill="#244064"/><text x="48" y="781" text-anchor="middle" font-size="12" font-weight="700" fill="#FFF">南</text><text x="76" y="774" font-size="12" fill="#FFF">南哥</text><text x="76" y="792" font-size="10" fill="#9FB2CB">SUPER_ADMIN</text><rect x="228" width="972" height="74" fill="#FFF"/><text x="262" y="37" font-size="21" font-weight="700" fill="#142540">'+(E $title)+'</text><text x="262" y="58" font-size="11" fill="#7A8799">'+(E $sub)+'</text><circle cx="1150" cy="36" r="18" fill="#EAF2FF"/><text x="1150" y="41" text-anchor="middle" font-size="12" font-weight="700" fill="#195BB8">南</text>'
  return $s
}
function End-Svg { '</g></svg>' }
function Button([int]$x,[int]$y,[int]$w,[string]$label,[string]$kind='primary') { $fill=$(if($kind -eq 'primary'){'#195BB8'}elseif($kind -eq 'danger'){'#C44E4E'}else{'#FFFFFF'}); $text=$(if($kind -in @('primary','danger')){'#FFFFFF'}else{'#195BB8'}); '<rect x="'+$x+'" y="'+$y+'" width="'+$w+'" height="40" rx="12" fill="'+$fill+'" '+$(if($kind -eq 'secondary'){'stroke="#CBD7E6"'}else{''})+'/><text x="'+($x+$w/2)+'" y="'+($y+25)+'" text-anchor="middle" font-size="13" font-weight="700" fill="'+$text+'">'+(E $label)+'</text>' }
function Filters([string[]]$items,[string]$action) { $s='<rect x="252" y="98" width="924" height="76" rx="18" fill="#FFF" filter="url(#s)"/>'; $x=274; foreach($i in $items){$s+='<rect x="'+$x+'" y="116" width="158" height="40" rx="12" fill="#F7F9FC" stroke="#E1E7EF"/><text x="'+($x+16)+'" y="141" font-size="12" fill="#7A8799">'+(E $i)+'</text>'; $x+=172}; if($action){$s+=Button 1032 116 122 $action}; $s }
function Table([string[]]$headers,[object[]]$rows,[string]$hint='') { $s='<rect x="252" y="194" width="924" height="578" rx="18" fill="#FFF"/><text x="276" y="226" font-size="15" font-weight="700" fill="#142540">数据列表</text><text x="1150" y="226" text-anchor="end" font-size="11" fill="#7A8799">'+(E $hint)+'</text><rect x="272" y="246" width="884" height="42" rx="10" fill="#F4F7FB"/>'; $cw=[math]::Floor(884/$headers.Count); for($i=0;$i -lt $headers.Count;$i++){$s+='<text x="'+(286+$i*$cw)+'" y="272" font-size="11" font-weight="700" fill="#68768C">'+(E $headers[$i])+'</text>'}; $y=316; foreach($r in $rows){$vals=@($r); for($i=0;$i -lt $vals.Count;$i++){$color=$(if($i -eq $vals.Count-1){'#195BB8'}else{'#263852'});$s+='<text x="'+(286+$i*$cw)+'" y="'+$y+'" font-size="11" fill="'+$color+'">'+(E ([string]$vals[$i]))+'</text>'}; $s+='<line x1="272" y1="'+($y+18)+'" x2="1156" y2="'+($y+18)+'" stroke="#EDF1F6"/>'; $y+=58}; $s+='<text x="276" y="748" font-size="11" fill="#8793A4">共 '+$rows.Count+' 条样例数据 · 第 1 页</text>'; $s }
function Fields([object[]]$sections,[string[]]$actions) { $s='';$y=102; foreach($sec in $sections){$s+='<rect x="252" y="'+$y+'" width="924" height="'+$sec.H+'" rx="18" fill="#FFF"/><text x="276" y="'+($y+32)+'" font-size="16" font-weight="700" fill="#142540">'+(E $sec.Title)+'</text>'; $fy=$y+56;$col=0; foreach($f in $sec.Fields){$x=276+($col%2)*438;$yy=$fy+[math]::Floor($col/2)*72;$s+='<text x="'+$x+'" y="'+$yy+'" font-size="11" fill="#68768C">'+(E $f[0])+'</text><rect x="'+$x+'" y="'+($yy+10)+'" width="408" height="38" rx="10" fill="#F7F9FC" stroke="#DDE4EE"/><text x="'+($x+14)+'" y="'+($yy+34)+'" font-size="12" fill="#263852">'+(E $f[1])+'</text>'; $col++}; $y+=$sec.H+18}; $x=1176; for($i=$actions.Count-1;$i -ge 0;$i--){$w=126;$x-=$w;$kind=$(if($i -eq $actions.Count-1){'primary'}else{'secondary'});$s+=Button $x 754 $w $actions[$i] $kind;$x-=12}; $s }
function Write-Screen([string]$file,[string]$svg){ Set-Content -LiteralPath (Join-Path $out $file) -Value $svg -Encoding UTF8 -NoNewline }

